// getpgrp() - Retrieves PGID of calling process
// Standard POSIX: pid_t getpgrp(void);

pid_t caller_pgid;
int err_code;

// Retrieve PGID of the current process
caller_pgid = getpgrp();

if (caller_pgid == -1) {
    err_code = errno;
    // Usually successful unless severe OS issue
}

